  var poz=function(){var m=k.querySelector('.wsleggings__km');if(!m||!m.offsetHeight)return;var t=(m.getBoundingClientRect().top-w.getBoundingClientRect().top)+m.offsetHeight/2;w.querySelectorAll('.wsleggings__pus').forEach(function(b){b.style.top=t+'px';});};
  poz();window.addEventListener('resize',poz);window.addEventListener('load',poz);k.querySelectorAll('img,video').forEach(function(e){e.addEventListener('load',poz);e.addEventListener('loadedmetadata',poz);});
});})();
